}

.modal-dialog h4 {
    margin-bottom: 1rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

/* Appearance */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-label input[type="radio"] {
    accent-color: #0d6efd;
}

/* Preview Area */
.preview-area {
    margin-top: 2rem;
    padding: 1.5rem;
    border: 2px dashed #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.3s;
}

.preview-area h4 {
    margin-bottom: 0.75rem;
}

.preview-area.theme-dark {
    background: #1a1a2e;
    color: #e0e0e0;
