}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border-radius: 0.375rem;
    background: rgba(128, 128, 128, 0.1);
